<script setup lang="ts">import {computed,ref,watch,onUnmounted} from 'vue';import {useRoute} from 'vue-router';import {RefreshCw,ArrowRight} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createComparison,retryComparison,getComparison} from '../api/comparisons';import {ComparisonDetail} from '../types/comparison';import StudySelector from '../components/StudySelector.vue';import SensitivityPanel from '../components/SensitivityPanel.vue';import StatusBadge from '../components/common/StatusBadge.vue';import DataTable from '../components/common/DataTable.vue';import Notice from '../components/common/Notice.vue';import {time} from '../utils/format';const s=useResearchData(true),auth=useAuth(),a=useAction(),route=useRoute(),id=ref(Number(route.query.study)||0),name=ref(''),ratioText=ref('.0001, .001, .01, .1'),B=ref(199),seed=ref(2026),selected=ref(Number(route.query.comparison)||0),detail=ref<ComparisonDetail|null>(null);const study=computed(()=>s.studies.find(x=>x.id===id.value)||s.studies[0]);const ratios=computed(()=>ratioText.value.split(/[,，\s]+/).filter(Boolean).map(Number));const ratioError=computed(()=>{const v=ratios.value;if(v.length<2||v.length>8)return'请输入2–8个不重复比例';if(v.some(x=>!Number.isFinite(x)||x<=0||x>=1))return'每个比例须在(0,1)之间';if(new Set(v).size!==v.length)return'比例不能重复';return''});const blocking=computed(()=>s.comparisons.filter(c=>c.blocking&&c.study_id===study.value?.id));async function submit(){if(ratioError.value)return;a.execute(async()=>{const r=await createComparison({name:name.value,study_id:study.value.id,ratios:ratios.value,permutations:B.value,seed:seed.value});selected.value=r.id;await s.refresh();await load()})}function retry(){a.execute(async()=>{const r=await retryComparison(selected.value);selected.value=r.id;await s.refresh();await load()})}async function load(){if(!selected.value){detail.value=null;return}try{detail.value=await getComparison(selected.value)}catch{detail.value=null}}const poll=setInterval(async()=>{await s.refresh();const current=s.comparisons.find(c=>c.id===selected.value);if(current&&current.status!=='completed'&&current.status!=='failed')await load()},2000);onUnmounted(()=>clearInterval(poll));watch(selected,load,{immediate:true});</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">SENSITIVITY ACROSS REPLACEMENT RATIOS / 07</p><h1>零替换敏感性比较<span>一次冻结样本、组别与置换，换多个δ看结论是否改变。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><div v-if="blocking.length" class="notice"><b>{{blocking.length}}个未完成比较阻塞本研究的补样审批与导出：</b>{{blocking.map(c=>'#'+c.id+' '+c.status).join('、')}}。整组比较不发布时不开放补样审批或导出；失败比较可重试，重试沿用原始快照。</div><div class="editor-grid"><form @submit.prevent="submit"><label>比较名称<input aria-label="比较名称" v-model="name" minlength="2" maxlength="160" required placeholder="例如：零替换比例敏感性复核" :disabled="auth.user?.role==='viewer'"/></label><StudySelector :studies="s.studies" :model-value="study?.id||0" @update:model-value="id=$event"/><div v-if="study" class="source-note"><b>{{study.reason}}</b><p>{{study.sample_count}}样本 / {{study.zero_rows}}行含零 / {{Object.entries(study.group_counts).map(([g,n])=>g+' '+n).join(' / ')}}</p></div><div class="form-heading"><span>01</span><h2>多种零替换比例</h2></div><label>δ列表 / 逗号或空格分隔<input aria-label="零替换比例列表" v-model="ratioText" :disabled="auth.user?.role==='viewer'" placeholder=".0001, .001, .01, .1"/></label><p :class="['caption',ratioError?'warning':'']">{{ratioError||'一次比较2–8个比例；每个比例逐行要求0<δ<1/z。整组一起发布，任一失败则不发布。'}}</p><div class="form-heading"><span>02</span><h2>共用置换条件</h2></div><div class="form-row"><label>置换次数<input aria-label="置换次数" type="number" min="199" max="999" v-model.number="B"/></label><label>根随机种子<input aria-label="随机种子" type="number" min="0" max="2147483647" v-model.number="seed"/></label></div><p class="caption">所有比例共用同一份置换标签序列，样本数×置换数≤150000。快照冻结后修改样本批注不影响历史比较。</p><button v-if="auth.user?.role!=='viewer'" class="primary" type="submit" :disabled="a.busy.value||!study?.supported||!!ratioError">建立敏感性比较 <ArrowRight :size="15"/></button><p v-else class="role-note">阅读者可核对已完成比较，提交需要研究员权限。</p></form><aside class="method-note"><span class="eyebrow">SENSITIVITY NOTE / 30</span><h2>只换假设，<br/>不换样本。</h2><ol><li><b>同一份冻结快照</b><p>样本、组别与组规模取自同一研究快照；开始后批注不回写历史比较。</p></li><li><b>同一份置换序列</b><p>每个δ使用相同seed生成的同一标签序列，差异只来自δ与数据变换。</p></li><li><b>整组原子发布</b><p>任一比例失败，整组比较不发布；失败记录保留错误，重试沿用原始快照。</p></li></ol></aside></div><div class="section-heading"><h2>比较档案</h2><span>完成比较保持可读；失败比较可重试</span></div><DataTable :head="['#','名称','研究','δ','状态','结论变化','提交者','时间']"><tr v-for="c in s.comparisons" :key="c.id" :class="{selected:c.id===selected}" @click="selected=c.id"><td>{{c.id}}<small v-if="c.retry_of">重试 #{{c.retry_of}}</small></td><td><b>{{c.name}}</b></td><td>{{c.study_code}}</td><td>{{c.ratios.join(' / ')}}</td><td><StatusBadge :status="c.status"/></td><td>{{c.published?(c.summary?.changed?'结论随δ改变':'结论保持一致'):(c.blocking?'阻塞审批/导出':'未发布')}}</td><td>{{c.owner}}</td><td>{{time(c.created_at)}}</td></tr></DataTable><p v-if="!s.comparisons.length" class="empty">还没有敏感性比较。选择一个含零研究，一次提交多个δ。</p><template v-if="detail"><div class="run-summary"><div><span class="eyebrow">{{detail.study_code}} / SENSITIVITY</span><h3>{{detail.name}}</h3><p>{{detail.deltas.length}}个比例 · {{detail.permutations}}次置换 · seed {{detail.seed}}<span v-if="detail.retry_of"> · 重试自 #{{detail.retry_of}}</span></p></div><div><span>状态</span><StatusBadge :status="detail.status"/><small>{{detail.published?'整组已发布':'未发布'}}</small></div><div><span>冻结样本 / 零行</span><b>{{detail.result?.frozen?.sample_count||'—'}}<em> / {{detail.result?.frozen?.zero_rows??'—'}}</em></b><small>批注冻结后不改历史依据</small></div></div><template v-if="detail.published&&detail.result"><SensitivityPanel :result="detail.result"/></template><div v-else class="pending"><h2>{{detail.status==='failed'?'比较失败，整组未发布':detail.status==='completed'?'比较结果缺失':'独立worker正在逐比例计算'}}</h2><p>{{detail.error||'每个δ使用同一冻结快照与置换序列；任一失败则整组不发布。'}}</p><button v-if="detail.status==='failed'&&auth.user?.role!=='viewer'" class="outline" :disabled="a.busy.value" @click="retry"><RefreshCw :size="14"/>沿用原始快照重试</button><p v-if="detail.status==='failed'" class="caption">重试会从原始冻结快照重新计算；此前已完成的比较保持可读。</p></div></template></div></template>
